parameters.jsCode:
const graded = $('Conformance Gate vs Config.md').all();
const agent = $input.first().json;
const parsed = (agent && agent.output) ? agent.output : agent;
const verdict = String((parsed && parsed.verdict) || 'REJECTED').toUpperCase();
const blocking = (parsed && parsed.blocking_defects) || [];
const advisory = (parsed && parsed.advisory_notes) || [];
const evidence = String((parsed && parsed.evidence) || '').trim();

const conformantAll = graded.length > 0 && graded.every(function (g) { return g.json.conformant === true; });
const reviewConfirmed = verdict === 'CONFIRMED' && blocking.length === 0 && evidence.length > 0;
const releasable = conformantAll && reviewConfirmed;

const allDefects = [];
for (const g of graded) {
  for (const d of g.json.conformance_defects) allDefects.push(g.json.model + ' :: ' + d);
}
for (const b of blocking) allDefects.push('REVIEWER :: ' + b);

const allWarnings = [];
for (const g of graded) {
  for (const w of (g.json.conformance_warnings || [])) allWarnings.push(g.json.model + ' :: ' + w);
}
for (const a of advisory) allWarnings.push('REVIEWER :: ' + a);

const first = graded.length ? graded[0].json : {};
let spend = 0;
for (const g of graded) spend += (g.json.actual_cost_usd || 0);

return [{ json: {
  run_id: first.run_id || null,
  attempt: first.attempt || 1,
  releasable: releasable,
  conformant_all: conformantAll,
  review_verdict: verdict,
  review_confirmed: reviewConfirmed,
  review_confidence: (parsed && parsed.confidence) || 0,
  review_evidence: evidence,
  advisory_notes: allWarnings,
  blocking_defects: allDefects,
  voice_source: first.voice_source || null,
  voice_is_cloned: first.voice_is_cloned === true,
  candidates: graded.map(function (g) {
    return { model: g.json.model, verdict: g.json.conformance_verdict, measured: g.json.measured_summary, content_url: g.json.content_url, cost_usd: g.json.actual_cost_usd, defects: g.json.conformance_defects };
  }),
  total_actual_cost_usd: Math.round(spend * 10000) / 10000,
  notify_email: first.notify_email || null,
  script_title: first.script_title || null,
  concept: first.concept || null
} }];

const review = $('Fold Review Verdict').first().json;
const approval = $('Approval - Publish To Production').first().json;
return [{ json: {
  statusCode: 200,
  ok: true,
  publish_mode: 'agent_gh_hook',
  run_id: review.run_id,
  candidates: review.candidates,
  chosen_model: approval.chosen_model,
  content_url: approval.content_url || ((review.candidates||[])[0]||{}).content_url,
  total_actual_cost_usd: review.total_actual_cost_usd,
  voice_is_cloned: review.voice_is_cloned,
  voice_source: review.voice_source,
  note: 'Agent commits assets via gh after releasable execution.'
} }];

const review = $('Fold Review Verdict').first().json;
const chosen = (review.candidates && review.candidates.length) ? review.candidates[0].model : null;
return [{ json: {
  publish_decision: 'PUBLISH',
  'Publish to production?': 'PUBLISH',
  chosen_model: chosen,
  'Which candidate ships (model id, blank = first conformant)': chosen || '',
  publish_note: 'adversarial_auto',
  'Note for the execution log': 'adversarial_auto',
  approval_mode: 'adversarial_auto',
  content_url: (review.candidates && review.candidates[0] && review.candidates[0].content_url) || null,
  candidates: review.candidates || [],
  run_id: review.run_id,
  total_actual_cost_usd: review.total_actual_cost_usd
} }];

const pub = $('Email Publish-Approval Link').first().json;
const body = pub.body || pub;
const ok = (pub.statusCode === 200) || (body && body.ok === true);
return [{ json: {
  statusCode: ok ? 204 : 500,
  body: body,
  note: 'Deploy dispatched by publish hook (gh); this node is a pass-through for topology parity.'
} }];

const review = $('Fold Review Verdict').first().json;
const approvalRaw = $('Approval - Publish To Production').first().json;
const deploy = $('Dispatch CI and Deploy').first().json;
const site = $('Verify Production Site').first().json;
const asset = $('Verify Avatar Assets Live').first().json;

function formField(obj, machineKey, humanLabel) {
  if (obj && obj[machineKey] !== undefined) return obj[machineKey];
  if (obj && obj[humanLabel] !== undefined) return obj[humanLabel];
  return undefined;
}
const publishDecision = formField(approvalRaw, 'publish_decision', 'Publish to production?');
const chosenModel = formField(approvalRaw, 'chosen_model', 'Which candidate ships (model id, blank = first conformant)');
const publishNote = formField(approvalRaw, 'publish_note', 'Note for the execution log');

const checks = [];
function check(name, pass, detail) { checks.push({ check: name, pass: !!pass, detail: detail }); }

check('conformance_all_candidates', review.conformant_all, review.candidates.map(function (c) { return c.model + '=' + c.verdict; }).join(', '));
check('independent_review_confirmed', review.review_confirmed, review.review_verdict + ' @ ' + review.review_confidence + ' :: ' + review.review_evidence);
check('adversarial_auto_publish', publishDecision === 'PUBLISH', String(publishDecision) + ' mode=adversarial_auto');
check('ci_deploy_dispatched', deploy && (deploy.statusCode === 204 || deploy.statusCode === 200), 'github workflow_dispatch HTTP ' + (deploy && deploy.statusCode));
check('production_reachable', site && site.statusCode === 200, 'GET / HTTP ' + (site && site.statusCode));
const assetType = (asset && asset.headers) ? (asset.headers['content-type'] || '') : '';
check('avatar_asset_served', asset && asset.statusCode === 200 && assetType.indexOf('video') !== -1, 'GET /assets/my-hero-avatar.mp4 HTTP ' + (asset && asset.statusCode) + ' type=' + assetType);

const failed = checks.filter(function (c) { return !c.pass; });

return [{ json: {
  status: failed.length === 0 ? 'DELIVERED' : 'DELIVERED_WITH_UNVERIFIED_STEPS',
  run_id: review.run_id,
  attempt: review.attempt,
  concept: review.concept,
  script_title: review.script_title,
  voice_source: review.voice_source,
  voice_is_cloned: review.voice_is_cloned,
  candidates: review.candidates,
  chosen_model: chosenModel || (review.candidates.length ? review.candidates[0].model : null),
  actual_spend_usd: review.total_actual_cost_usd,
  checks: checks,
  failed_checks: failed.map(function (c) { return c.check + ': ' + c.detail; }),
  advisory_notes: review.advisory_notes,
  owner_note: publishNote || '',
  delivered_at: new Date().toISOString(),
  feedback_loop: failed.length === 0 ? 'closed - every gate green with an artifact behind it' : 'open - the listed checks could not be evidenced and must not be reported as done'
} }];

const v = $input.first().json;
const plan = $('Resolve Generation Plan').first().json;
const MAX_ATTEMPTS = 3;
const next = (v.attempt || 1) + 1;
const spent = v.total_actual_cost_usd || 0;
const perAttempt = plan.estimated_cost_usd || 0;
const ceiling = plan.max_spend_usd || 0;
const wouldSpend = spent + perAttempt;

const budgetLeft = next <= MAX_ATTEMPTS;
const spendLeft = wouldSpend <= ceiling;

const out = Object.assign({}, plan);
out.attempt = next;
out.max_attempts = MAX_ATTEMPTS;
out.prior_defects = v.blocking_defects || [];
out.prior_verdict = v.review_verdict;
out.spent_so_far_usd = Math.round(spent * 10000) / 10000;
out.would_spend_usd = Math.round(wouldSpend * 10000) / 10000;
out.can_retry = budgetLeft && spendLeft;
if (!budgetLeft) {
  out.retry_block_reason = 'attempt ' + next + ' would exceed the ' + MAX_ATTEMPTS + '-attempt limit';
} else if (!spendLeft) {
  out.retry_block_reason = 'cumulative spend would reach $' + wouldSpend.toFixed(2) + ', above the $' + Number(ceiling).toFixed(2) + ' ceiling for this run';
} else {
  out.retry_block_reason = null;
}
out.concept = plan.concept + '\n\nATTEMPT ' + (next - 1) + ' WAS REJECTED. Correct these named defects and do not repeat them:\n- ' + (v.blocking_defects || []).join('\n- ');
return [{ json: out }];

