const rows = $input.all();
const row = rows.length ? rows[0].json : null;
if (!row || !row.payload_b64) {
  return [{ json: { found: false, message: 'asset token not found or expired' } }];
}
const buf = Buffer.from(row.payload_b64, 'base64');
const ext = row.mime === 'audio/mpeg' ? 'mp3' : 'bin';
return [{
  json: { found: true, bytes: buf.length, mime: row.mime, token: row.token },
  binary: { data: { data: row.payload_b64, mimeType: row.mime, fileName: 'voice.' + ext, fileExtension: ext, fileSize: String(buf.length) } }
}];

const raw = $input.first().json;
const body = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;
function firstNonEmpty(a, b, fallback) {
  if (a !== undefined && a !== null && String(a).trim() !== '') return a;
  if (b !== undefined && b !== null && String(b).trim() !== '') return b;
  return fallback;
}
function toList(v) {
  if (Array.isArray(v)) return v;
  if (v === undefined || v === null) return [];
  return String(v).split(',').map(function (s) { return s.trim(); }).filter(Boolean);
}
const brief = {
  run_id: String($execution.id),
  concept: String(firstNonEmpty(body.concept, raw.concept, '')).trim(),
  expertise_anchor: String(firstNonEmpty(body.expertise_anchor, raw.expertise_anchor, '')).trim(),
  portrait_url: String(firstNonEmpty(body.portrait_url, raw.portrait_url, 'https://forgotten-mistory.web.app/assets/my_avatar.png')).trim(),
  voice_source: String(firstNonEmpty(body.voice_source, raw.voice_source, 'ELEVENLABS_ARCHIVE')).trim(),
  voice_id: String(firstNonEmpty(body.voice_id, raw.voice_id, '0ZJ4kFDo6bZUNQsuULOW')).trim(),
  archive_history_id: String(firstNonEmpty(body.archive_history_id, raw.archive_history_id, 'ne5CsHxigdTwNHfuZwKv')).trim(),
  duration_seconds: parseInt(String(firstNonEmpty(body.duration_seconds, raw.duration_seconds, '10')), 10),
  aspect_ratio: String(firstNonEmpty(body.aspect_ratio, raw.aspect_ratio, '16:9')).trim(),
  delivery_profile: String(firstNonEmpty(body.delivery_profile, raw.delivery_profile, 'MASTER_1080')).trim(),
  models: toList(firstNonEmpty(body.models, raw.models, 'heygen/avatar-iv')),
  max_spend_usd: parseFloat(String(firstNonEmpty(body.max_spend_usd, raw.max_spend_usd, '35'))),
  notify_email: String(firstNonEmpty(body.notify_email, raw.notify_email, '')).trim(),
  attempt: 1
};
const VALID_PROFILES = ['WEB_PARITY', 'MASTER_1080'];
const VALID_ASPECTS = ['16:9', '9:16', '1:1'];
const VALID_SOURCES = ['ELEVENLABS_ARCHIVE', 'ELEVENLABS_LIVE', 'MODEL_NATIVE'];
const VALID_DURATIONS = [6, 8, 10, 12, 15];
const errors = [];
if (!brief.concept) errors.push('concept is required');
if (!brief.expertise_anchor) errors.push('expertise_anchor is required');
if (!/^https:\/\//.test(brief.portrait_url)) errors.push('portrait_url must be a public https:// URL - the generator fetches it and only HTTPS is accepted');
if (VALID_SOURCES.indexOf(brief.voice_source) === -1) errors.push('voice_source must be one of ' + VALID_SOURCES.join(', '));
if (VALID_PROFILES.indexOf(brief.delivery_profile) === -1) errors.push('delivery_profile must be one of ' + VALID_PROFILES.join(', ') + ' - got "' + brief.delivery_profile + '"');
if (VALID_ASPECTS.indexOf(brief.aspect_ratio) === -1) errors.push('aspect_ratio must be one of ' + VALID_ASPECTS.join(', ') + ' - got "' + brief.aspect_ratio + '"');
if (!isFinite(brief.duration_seconds) || VALID_DURATIONS.indexOf(brief.duration_seconds) === -1) errors.push('duration_seconds must be one of ' + VALID_DURATIONS.join(', '));
if (brief.voice_source === 'ELEVENLABS_LIVE' && !brief.voice_id) errors.push('voice_id is required in ELEVENLABS_LIVE mode');
if (brief.voice_source === 'ELEVENLABS_ARCHIVE' && !brief.archive_history_id) errors.push('archive_history_id is required in ELEVENLABS_ARCHIVE mode - pick one from GET https://api.elevenlabs.io/v1/history');
if (!brief.models.length) errors.push('at least one model must be selected');
if (!isFinite(brief.max_spend_usd) || brief.max_spend_usd <= 0) errors.push('max_spend_usd must be a positive number');
brief.input_errors = errors;
brief.input_valid = errors.length === 0;
return [{ json: brief }];

const brief = $('Normalise Brief').first().json;
const orRes = $('Preflight OpenRouter Key').first().json;
const elRes = $('Preflight ElevenLabs Voice').first().json;
const subRes = $('Preflight Voice Entitlement').first().json;
const blockers = [];
const advisories = [];

if (!brief.input_valid) {
  for (const e of brief.input_errors) blockers.push('BRIEF: ' + e);
}

if (!orRes || orRes.statusCode !== 200) {
  blockers.push('OPENROUTER: key check returned HTTP ' + (orRes && orRes.statusCode) + '. Point the "OpenRouter - Avatar Studio" credential at a valid sk-or-v1 key.');
}

const needsElevenLabs = brief.voice_source === 'ELEVENLABS_LIVE' || brief.voice_source === 'ELEVENLABS_ARCHIVE';
if (needsElevenLabs) {
  if (!elRes || elRes.statusCode !== 200) {
    blockers.push('ELEVENLABS: voice ' + brief.voice_id + ' returned HTTP ' + (elRes && elRes.statusCode) + '. The "ElevenLabs API" credential must send header xi-api-key with a key starting sk_. A key ID is not a key.');
  }
}

const sub = (subRes && subRes.body) || {};
if (brief.voice_source === 'ELEVENLABS_LIVE') {
  if (!subRes || subRes.statusCode !== 200) {
    blockers.push('ELEVENLABS: subscription probe returned HTTP ' + (subRes && subRes.statusCode) + '.');
  } else if (sub.can_use_instant_voice_cloning === false) {
    blockers.push('ELEVENLABS PLAN: can_use_instant_voice_cloning is false on tier "' + sub.tier + '". Synthesising fresh speech from an Instant Voice Clone needs Starter or above. The API key is valid and correctly scoped - the plan is the limit. Either upgrade, or re-run with voice_source=ELEVENLABS_ARCHIVE which reuses already-rendered audio in the same cloned voice. Halting before any OpenRouter spend.');
  } else {
    const left = (sub.character_limit || 0) - (sub.character_count || 0);
    if (left < 500) advisories.push('ELEVENLABS QUOTA: only ' + left + ' characters remain this period.');
  }
}
if (brief.voice_source === 'MODEL_NATIVE') {
  advisories.push('VOICE: MODEL_NATIVE selected. The video model generates the speech with its own synthetic voice. This is NOT your cloned voice and must not be presented as such.');
}
if (brief.voice_source === 'ELEVENLABS_ARCHIVE') {
  advisories.push('VOICE: ELEVENLABS_ARCHIVE selected. Audio is your real cloned voice, but the spoken words are fixed by history item ' + brief.archive_history_id + ' - the generated script drives framing and motion only, not the words heard.');
}

const out = Object.assign({}, brief);
out.preflight_blockers = blockers;
out.preflight_advisories = advisories;
out.preflight_ok = blockers.length === 0;
out.openrouter_usage_usd = (orRes && orRes.body && orRes.body.data && orRes.body.data.usage) || null;
out.voice_name = (elRes && elRes.body && elRes.body.name) || null;
out.voice_category = (elRes && elRes.body && elRes.body.category) || null;
out.elevenlabs_tier = sub.tier || null;
out.can_use_ivc = sub.can_use_instant_voice_cloning === true;
return [{ json: out }];

const brief = $input.first().json;

const CONFIG = {
