  'google/veo-3.1-lite': { max_resolution: '1080p', resolutions: ['720p', '1080p'], aspects: ['16:9', '9:16'], durations: [4, 6, 8], audio_out: true, seed: true, frame_images: ['first_frame', 'last_frame'], needs_image: false, price_per_second: 0.08, passthrough: [] },
