};

const RES_RANK = { '480p': 480, '720p': 720, '768p': 768, '1080p': 1080, '2K': 1440, '4K': 2160 };

function seedFor(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h = h ^ text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h) % 2147483647;
}

function nearestDuration(list, want) {
  if (!list) return want;
  let best = list[0];
  let bestDiff = Math.abs(list[0] - want);
  for (const d of list) {
    const diff = Math.abs(d - want);
    if (diff < bestDiff) { best = d; bestDiff = diff; }
  }
  return best;
}

const target = CONFIG.profiles[brief.delivery_profile];
const wantRank = RES_RANK[target.resolution];
const seed = seedFor(brief.concept + '|' + brief.expertise_anchor);
const tasks = [];
const notes = [];
let total = 0;

for (const modelId of brief.models) {
  const spec = MATRIX[modelId];
  if (!spec) { notes.push('SKIPPED ' + modelId + ' - not present in the verified OpenRouter video catalogue'); continue; }
