  }
  const body = { model: modelId, aspect_ratio: brief.aspect_ratio, resolution: chosen };
  if (spec.durations) body.duration = duration;
  if (spec.seed) body.seed = seed;
  const cost = Math.round(spec.price_per_second * duration * 100) / 100;
  tasks.push({
    run_id: brief.run_id,
    attempt: brief.attempt,
    model: modelId,
    request_skeleton: body,
    model_supports_audio_out: !!spec.audio_out,
    needs_image: !!spec.needs_image,
