  });
  total += cost;
}


// Gate O — iterate rung hard cap $6.00 (estimated refuse before submit)
const ITERATE_CAP = 6.0;
let iterateEst = 0;
for (const t of tasks) {
  if (t.model === 'bytedance/seedance-2.0-mini') iterateEst += t.estimated_cost_usd || 0;
