}

const ALL_R140 = ['google/veo-3.1-lite','bytedance/seedance-2.0-mini','bytedance/seedance-2.5','alibaba/wan-3.0','alibaba/wan-3.0-prime','heygen/avatar-iv','minimax/hailuo-3-max'];
