  'minimax/hailuo-3-max': 'No hero opening shot; greeting/title padding forbidden.',
  'google/veo-3.1-lite': 'Previz not requested in this brief.',
  'bytedance/seedance-2.0-mini': 'Iterate not requested in this brief.',
  'heygen/avatar-iv': 'Presenter not requested in this brief.'
};
