}
if (total > brief.max_spend_usd) {
  throw new Error('Estimated cost $' + total.toFixed(2) + ' exceeds your ceiling of $' + Number(brief.max_spend_usd).toFixed(2) + '. Reduce models, shorten duration, or raise the ceiling. Nothing was dispatched.');
