const BANNED_APOLOGETIC = ['sorry', 'apolog', 'unfortunately', 'i am afraid', "i'm afraid", 'disclaimer', 'i am not an expert', "i'm not an expert", 'i might be wrong', 'bear with me', 'hopefully', 'to be honest', 'i hope this helps', 'i am just', "i'm just", 'i am only', "i'm only", 'please forgive', 'i could be wrong', 'forgive me'];
const BANNED_BOASTFUL = ['world-class', 'world class', 'cutting-edge', 'cutting edge', 'revolutionary', 'best-in-class', 'best in class', 'game-changing', 'game changing', 'passionate', 'guru', 'ninja', 'rockstar', 'unparalleled', 'unmatched'];
const BANNED_FORMAT = ['[', ']', '*', '#', 'narrator:', 'vikram:', 'speaker:'];

const lower = script.toLowerCase();
const violations = [];
for (const t of BANNED_APOLOGETIC) { if (lower.indexOf(t) !== -1) violations.push('APOLOGETIC/DEFENSIVE: "' + t + '"'); }
