for (const t of BANNED_FORMAT) { if (lower.indexOf(t) !== -1) violations.push('NON-SPOKEN ARTEFACT: "' + t + '"'); }

const words = script.split(/\s+/).filter(Boolean).length;
const budget = Math.round((plan.duration_seconds / 60) * 150);
const ceiling = Math.ceil(budget * 1.15);
if (!script) violations.push('EMPTY SCRIPT');
if (words > ceiling && plan.voice_source !== 'ELEVENLABS_ARCHIVE') violations.push('OVER LENGTH: ' + words + ' words exceeds the ' + ceiling + '-word ceiling for ' + plan.duration_seconds + 's at 150 wpm - the avatar would desynchronise');

const out = Object.assign({}, plan);
out.attempt = attempt;
out.prior_defects = priorDefects;
out.spent_so_far_usd = spentSoFar;
out.script = script;
out.script_title = String((parsed && parsed.title) || '').trim();
out.motion_prompt = String((parsed && parsed.motion_prompt) || 'Head and shoulders framing, minimal gesture, steady eye contact').trim();
out.negative_prompt = String((parsed && parsed.negative_prompt) || 'text overlays, captions, watermarks, extra people, camera shake, distorted hands').trim();
out.evidence_line = String((parsed && parsed.evidence_line) || '').trim();
out.script_word_count = words;
out.script_word_budget = budget;
out.register_violations = violations;
out.register_clean = violations.length === 0;
const stampedTasks = [];
for (const t of plan.tasks) { stampedTasks.push(Object.assign({}, t, { attempt: attempt })); }
out.tasks = stampedTasks;
return [{ json: out }];

const plan = $input.first().json;
