const jobs = $('Keep Completed Renders').all();
const items = $input.all();
const out = [];

function walk(buf, start, end, want) {
  const found = [];
  let p = start;
  while (p + 8 <= end) {
    const size = buf.readUInt32BE(p);
    const type = buf.toString('latin1', p + 4, p + 8);
    let header = 8;
    let boxSize = size;
    if (size === 1) { boxSize = Number(buf.readBigUInt64BE(p + 8)); header = 16; }
    else if (size === 0) { boxSize = end - p; }
    if (boxSize < header || p + boxSize > end) break;
    if (type === want) found.push({ start: p + header, end: p + boxSize });
    p += boxSize;
  }
  return found;
}

function deepFind(buf, start, end, path) {
  let regions = [{ start: start, end: end }];
  for (const seg of path) {
    const next = [];
    for (const r of regions) {
      for (const h of walk(buf, r.start, r.end, seg)) next.push(h);
    }
    regions = next;
    if (!regions.length) return [];
  }
  return regions;
}

for (let i = 0; i < items.length; i++) {
  const job = (jobs[i] && jobs[i].json) ? jobs[i].json : {};
  let buf = null;
  try {
    if (this && this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
      buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    }
  } catch (e) { buf = null; }
  if (!buf) {
    try {
      const bin = items[i].binary;
      if (bin && bin.data && bin.data.data) buf = Buffer.from(bin.data.data, 'base64');
    } catch (e) { buf = null; }
  }
  const probe = { probe_ok: false, probe_error: null, bytes: buf ? buf.length : 0, width: null, height: null, fps: null, duration_s: null, codec: null, avc_profile: null, avc_profile_id: null, chroma_format: null, pix_fmt: null, has_audio: false, audio_codec: null };

  if (!buf || buf.length < 64) {
    probe.probe_error = 'no video bytes returned for ' + (job.model || 'unknown model') + ' - the download failed or produced an error item';
  } else {
    try {
      const moov = walk(buf, 0, buf.length, 'moov');
      if (!moov.length) {
        probe.probe_error = 'no moov box - not a parseable progressive MP4';
      } else {
        const m = moov[0];
        for (const trak of walk(buf, m.start, m.end, 'trak')) {
          const tkhd = walk(buf, trak.start, trak.end, 'tkhd');
          const mdhd = deepFind(buf, trak.start, trak.end, ['mdia', 'mdhd']);
          const stsd = deepFind(buf, trak.start, trak.end, ['mdia', 'minf', 'stbl', 'stsd']);
          const stsz = deepFind(buf, trak.start, trak.end, ['mdia', 'minf', 'stbl', 'stsz']);
          if (!stsd.length) continue;
          const sd = stsd[0];
          if (sd.start + 16 > sd.end) continue;
          const fmt = buf.toString('latin1', sd.start + 12, sd.start + 16);
          if (fmt === 'avc1' || fmt === 'avc3' || fmt === 'hev1' || fmt === 'hvc1') {
            probe.codec = (fmt === 'avc1' || fmt === 'avc3') ? 'h264' : 'hevc';
            const entry = sd.start + 8;
            if (entry + 36 <= sd.end) {
              probe.width = buf.readUInt16BE(entry + 32);
              probe.height = buf.readUInt16BE(entry + 34);
            }
            if (tkhd.length) {
              const t = tkhd[0];
              const ver = buf.readUInt8(t.start);
              const off = ver === 1 ? t.start + 88 : t.start + 76;
              if (off + 8 <= t.end) {
                const tw = buf.readUInt32BE(off) / 65536;
                const th = buf.readUInt32BE(off + 4) / 65536;
                if (tw > 0 && th > 0) { probe.width = Math.round(tw); probe.height = Math.round(th); }
              }
            }
            const avcc = walk(buf, entry + 86, sd.end, 'avcC');
            if (avcc.length) {
              const a = avcc[0];
              probe.avc_profile_id = buf.readUInt8(a.start + 1);
              if (probe.avc_profile_id === 100) probe.avc_profile = 'High';
              else if (probe.avc_profile_id === 77) probe.avc_profile = 'Main';
              else if (probe.avc_profile_id === 66) probe.avc_profile = 'Baseline';
              else probe.avc_profile = 'profile-' + probe.avc_profile_id;
              const numSps = buf.readUInt8(a.start + 5) & 31;
              let q = a.start + 6;
              for (let s = 0; s < numSps; s++) { q = q + 2 + buf.readUInt16BE(q); }
              if (q < a.end) {
                const numPps = buf.readUInt8(q);
                q = q + 1;
                for (let s = 0; s < numPps; s++) { q = q + 2 + buf.readUInt16BE(q); }
              }
              if ([100, 110, 122, 144].indexOf(probe.avc_profile_id) !== -1 && q < a.end) {
                probe.chroma_format = buf.readUInt8(q) & 3;
                if (probe.chroma_format === 0) probe.pix_fmt = 'yuv400p';
                else if (probe.chroma_format === 1) probe.pix_fmt = 'yuv420p';
                else if (probe.chroma_format === 2) probe.pix_fmt = 'yuv422p';
                else probe.pix_fmt = 'yuv444p';
              }
            }
            if (mdhd.length && stsz.length) {
              const d = mdhd[0];
              const dver = buf.readUInt8(d.start);
              const timescale = dver === 1 ? buf.readUInt32BE(d.start + 20) : buf.readUInt32BE(d.start + 12);
              const dur = dver === 1 ? Number(buf.readBigUInt64BE(d.start + 24)) : buf.readUInt32BE(d.start + 16);
              const sampleCount = buf.readUInt32BE(stsz[0].start + 8);
              if (timescale > 0 && dur > 0) {
                probe.duration_s = Math.round((dur / timescale) * 1000) / 1000;
                probe.fps = Math.round((sampleCount / (dur / timescale)) * 1000) / 1000;
              }
            }
          } else if (fmt === 'mp4a' || fmt === 'ac-3' || fmt === 'ec-3' || fmt === 'Opus') {
            probe.has_audio = true;
            probe.audio_codec = fmt === 'mp4a' ? 'aac' : fmt;
          }
        }
        probe.probe_ok = typeof probe.width === 'number' && typeof probe.height === 'number' && probe.width > 0 && probe.height > 0;
        if (!probe.probe_ok) probe.probe_error = 'moov parsed but no usable video sample description found (width/height resolved to ' + probe.width + 'x' + probe.height + ')';
      }
    } catch (e) {
      probe.probe_ok = false;
      probe.probe_error = 'MP4 parse threw: ' + (e && e.message ? e.message : String(e));
    }
  }
  out.push({ json: Object.assign({}, job, probe) });
}
return out;

const items = $input.all();
const out = [];
for (const item of items) {
  const v = item.json;
  const defects = [];
  const warnings = [];

  if (!v.probe_ok) {
    defects.push('R140-0 unmeasurable: ' + (v.probe_error || 'container could not be parsed'));
  } else {
    if (v.width !== v.target_width || v.height !== v.target_height) {
      defects.push('R140-1 dimensions: got ' + v.width + 'x' + v.height + ', R-140 master contract requires ' + v.target_width + 'x' + v.target_height);
    }
    // heygen/avatar-iv ships provider-native 25fps; accept 24±1 (24 or 25).
    if (v.fps === null || Math.abs(v.fps - v.target_fps) > 1.05) {
      defects.push('R140-2 frame rate: got ' + v.fps + ' fps, R-140 master contract allows ' + v.target_fps + '±1 (heygen native 25fps accepted)');
    } else if (Math.abs(v.fps - v.target_fps) > 0.05) {
      warnings.push('R140-2 frame rate: got ' + v.fps + ' fps vs target ' + v.target_fps + ' — within ±1 provider tolerance (heygen native)');
    }
    if (v.codec !== v.target_codec) {
      defects.push('R140-3 codec: got ' + v.codec + ', R-140 master contract requires ' + v.target_codec);
    }
    if (v.avc_profile !== v.target_profile_name) {
      defects.push('R140-4 H.264 profile: got ' + v.avc_profile + ', R-140 master contract requires ' + v.target_profile_name);
    }
    if (v.pix_fmt === null) {
      warnings.push('R140-5 pixel format not present in the avcC extension - unverified, not failed');
    } else if (v.pix_fmt !== v.target_pix_fmt) {
      defects.push('R140-5 pixel format: got ' + v.pix_fmt + ', R-140 master contract requires ' + v.target_pix_fmt);
    }
    if (v.bytes > v.target_max_bytes) {
      defects.push('R140-6 size budget: ' + v.bytes + ' bytes exceeds the ' + v.target_max_bytes + '-byte ceiling for profile ' + v.target_profile);
    }
    const wantRatio = v.target_width / v.target_height;
    const gotRatio = v.width / v.height;
    if (Math.abs(wantRatio - gotRatio) > 0.01) {
      defects.push('R140-7 aspect: got ' + gotRatio.toFixed(4) + ', R-140 master contract requires ' + wantRatio.toFixed(4) + ' - the portrait crop box would cut the subject');
    }
  }

  if (v.voice_is_cloned !== true) {
    warnings.push('VOICE-1 this asset does not carry the cloned voice (source ' + v.voice_source + '). It must never be published as Vikram speaking.');
  }

  const conformant = defects.length === 0;
  out.push({ json: Object.assign({}, v, {
    conformance_defects: defects,
    conformance_warnings: warnings,
    conformant: conformant,
    conformance_verdict: conformant ? 'CONFORMANT' : 'NON_CONFORMANT',
    measured_summary: v.probe_ok ? (v.width + 'x' + v.height + ' @ ' + v.fps + 'fps ' + v.codec + '/' + v.avc_profile + ' ' + (v.pix_fmt || 'pix?') + ' ' + v.bytes + 'B' + (v.has_audio ? ' +' + v.audio_codec : ' silent')) : 'UNMEASURABLE'
  }) });
}
return out;

